export const discoveryRegistry = DISCOVERY_REGISTRY;

export const DISCOVERY_MANIFEST: DiscoveryRegistryManifest = {
  registryVersion: 'v9.7.0-MCA7',
  lastUpdated: '2026-08-20T22:30:00Z',
  totalDiscoveries: DISCOVERY_REGISTRY.length,
  lockedCount: DISCOVERY_REGISTRY.filter(d => d.status === 'LOCK').length,
  entries: DISCOVERY_REGISTRY
};

export function getDiscoveryEntry(id: string): DiscoveryEntry | undefined {
  return DISCOVERY_REGISTRY.find(d => d.id === id);
}

export function getAllDiscoveries(): DiscoveryEntry[] {
  return DISCOVERY_REGISTRY;
}

export function filterDiscoveriesByCategory(category: string): DiscoveryEntry[] {
  return DISCOVERY_REGISTRY.filter(d => d.category === category);
}

export function searchDiscoveries(query: string): DiscoveryEntry[] {
  const q = query.toLowerCase().trim();
  if (!q) return DISCOVERY_REGISTRY;
  return DISCOVERY_REGISTRY.filter(
    d =>
      d.id.toLowerCase().includes(q) ||
      d.name.toLowerCase().includes(q) ||
      d.reason.toLowerCase().includes(q) ||
      d.tags.some(t => t.toLowerCase().includes(q)) ||
      d.moduleCodes.some(m => m.toLowerCase().includes(q))
  );
}
